import { desc, eq, like, or } from "drizzle-orm";
import type { Db } from "../db";
import { notes } from "../db/schema";
import type {
  CreateNoteInput,
  Note,
  NoteListQuery,
  UpdateNoteInput,
} from "../types/note";

export class NotesRepository {
  constructor(private readonly db: Db) {}

  async findAll(query: NoteListQuery = {}): Promise<Note[]> {
    const search = query.search?.trim();

    const rows = search
      ? await this.db
          .select()
          .from(notes)
          .where(
            or(
              like(notes.title, `%${search}%`),
              like(notes.content, `%${search}%`),
            ),
          )
          .orderBy(desc(notes.updatedAt))
      : await this.db
          .select()
          .from(notes)
          .orderBy(desc(notes.updatedAt));

    return rows.map(mapNote);
  }

  async findById(id: number): Promise<Note | null> {
    const [row] = await this.db
      .select()
      .from(notes)
      .where(eq(notes.id, id))
      .limit(1);

    return row ? mapNote(row) : null;
  }

  async create(input: CreateNoteInput): Promise<Note> {
    const [row] = await this.db
      .insert(notes)
      .values({
        title: input.title ?? "",
        content: input.content ?? "",
      })
      .returning();

    return mapNote(row);
  }

  async update(id: number, input: UpdateNoteInput): Promise<Note | null> {
    const [row] = await this.db
      .update(notes)
      .set({
        ...(input.title !== undefined ? { title: input.title } : {}),
        ...(input.content !== undefined ? { content: input.content } : {}),
        updatedAt: new Date().toISOString(),
      })
      .where(eq(notes.id, id))
      .returning();

    return row ? mapNote(row) : null;
  }

  async delete(id: number): Promise<boolean> {
    const result = await this.db.delete(notes).where(eq(notes.id, id));
    return result.changes > 0;
  }
}

function mapNote(row: typeof notes.$inferSelect): Note {
  return {
    id: row.id,
    title: row.title,
    content: row.content,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}

import { Elysia, t } from "elysia";
import {
  NoteNotFoundError,
  NotesService,
  ValidationError,
} from "../services/notes.service";
import { errorResponse, successResponse } from "../types/api-response";

const noteBodySchema = t.Object({
  title: t.Optional(t.String({ maxLength: 500 })),
  content: t.Optional(t.String({ maxLength: 100_000 })),
});

export function createNotesRoutes(notesService: NotesService) {
  return new Elysia({ prefix: "/notes" })
    .get(
      "/",
      async ({ query }) =>
        successResponse(
          await notesService.listNotes({
            search: query.search,
          }),
        ),
      {
        query: t.Object({
          search: t.Optional(t.String()),
        }),
      },
    )
    .get(
      "/:id",
      async ({ params }) =>
        successResponse(await notesService.getNote(Number(params.id))),
      {
        params: t.Object({
          id: t.Numeric({ minimum: 1 }),
        }),
      },
    )
    .post(
      "/",
      async ({ body, set }) => {
        const note = await notesService.createNote(body);
        set.status = 201;
        return successResponse(note);
      },
      {
        body: noteBodySchema,
      },
    )
    .put(
      "/:id",
      async ({ params, body }) =>
        successResponse(
          await notesService.updateNote(Number(params.id), body),
        ),
      {
        params: t.Object({
          id: t.Numeric({ minimum: 1 }),
        }),
        body: noteBodySchema,
      },
    )
    .delete(
      "/:id",
      async ({ params }) => {
        await notesService.deleteNote(Number(params.id));
        return successResponse(null);
      },
      {
        params: t.Object({
          id: t.Numeric({ minimum: 1 }),
        }),
      },
    )
    .onError(({ error, set }) => {
      if (error instanceof NoteNotFoundError) {
        set.status = 404;
        return errorResponse(error.message);
      }

      if (error instanceof ValidationError) {
        set.status = 400;
        return errorResponse(error.message);
      }

      if (error instanceof Error && error.name === "ValidationError") {
        set.status = 400;
        return errorResponse(error.message);
      }

      set.status = 500;
      return errorResponse("Internal server error");
    });
}

import type { NotesRepository } from "../repositories/notes.repository";
import type {
  CreateNoteInput,
  Note,
  NoteListQuery,
  UpdateNoteInput,
} from "../types/note";

export class NotesService {
  constructor(private readonly notesRepository: NotesRepository) {}

  listNotes(query: NoteListQuery = {}): Promise<Note[]> {
    return this.notesRepository.findAll(query);
  }

  async getNote(id: number): Promise<Note> {
    const note = await this.notesRepository.findById(id);

    if (!note) {
      throw new NoteNotFoundError(id);
    }

    return note;
  }

  createNote(input: CreateNoteInput): Promise<Note> {
    return this.notesRepository.create(input);
  }

  async updateNote(id: number, input: UpdateNoteInput): Promise<Note> {
    const note = await this.notesRepository.update(id, input);

    if (!note) {
      throw new NoteNotFoundError(id);
    }

    return note;
  }

  async deleteNote(id: number): Promise<void> {
    const deleted = await this.notesRepository.delete(id);

    if (!deleted) {
      throw new NoteNotFoundError(id);
    }
  }
}

export class NoteNotFoundError extends Error {
  constructor(public readonly id: number) {
    super(`Note with id ${id} not found`);
    this.name = "NoteNotFoundError";
  }
}

export class ValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ValidationError";
  }
}

export interface ApiSuccessResponse<T> {
  success: true;
  data: T;
}

export interface ApiErrorResponse {
  success: false;
  message: string;
}

export type ApiResponse<T> = ApiSuccessResponse<T> | ApiErrorResponse;

export function successResponse<T>(data: T): ApiSuccessResponse<T> {
  return { success: true, data };
}

export function errorResponse(message: string): ApiErrorResponse {
  return { success: false, message };
}

